///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_SignCallback
 * @description Sign Callback 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_SignCallback = async function () {
    const sbmOptions = {
        id: "tx_SignCallback",
        method: "post",
        action: "/esg/writeESGSubmitInfoForm.do?method=executeCertificate",
        ref: "dma_SignCallbackReq",
        target: "dlt_resultVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/esg/writeESGSubmitInfoForm.do?method=registerESGSubmitInformation",
        ref: "dma_submitReq",
        target: "dlt_resultVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name SignCallback
 * @description Sign Callback 처리
 * @param {*} result result
 * @param {*} postData postData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.SignCallback = async function (result, postData) {
    (document.certiFrm || { elements: [] }).target = 'certiFrame';
    (document.certiFrm || { elements: [] }).action = "/esg/writeESGSubmitInfoForm.do?method=executeCertificate";
    $c.util.getComponent('dma_SignCallbackReq').set('PKCS7SignedData', result);
    if (result) {
        await scwin.tx_SignCallback();
    } else {
        if (INI_ALERT) {
            INI_ALERT("전자서명에 실패하였습니다.");
        } else {
            await $c.win.alert("전자서명에 실패하였습니다.");
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initCallBack
 * @description init Call Back 처리
 * @param {*} result result
 * @returns {void}
 * @hidden N
 */
scwin.initCallBack = function (result) {
    return;
};

/**
 * @method
 * @name checkFreedomDisclosure
 * @description check Freedom Disclosure 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFreedomDisclosure = async function () {
    if (ipt_mainFormNameCheckBox.checked) {
        txt_mainFormName.textContent += '(자율공시)';
        await $c.win.alert('시가총액 5000억 이하인 회사만 자율공시를 체크해주세요.');
        $c.util.getComponent('dma_SignCallbackReq').set('disclsTitle', '자율공시');
    } else {
        const currentText = txt_mainFormName.textContent;
        if (scwin.strEndsWith(currentText, '(자율공시)')) {
            txt_mainFormName.textContent = scwin.sliceString(currentText, 0, -6);
            $c.util.getComponent('dma_SignCallbackReq').set('disclsTitle', '');
        }
    }
};

/**
 * @method
 * @name strEndsWith
 * @description str Ends With 처리
 * @param {String} str str
 * @param {String} searchStr searchStr
 * @returns {void}
 * @hidden N
 */
scwin.strEndsWith = function (str, searchStr) {
    let position = str.length;
    position -= searchStr.length;
    return str.substring(position, position + searchStr.length) === searchStr;
};

/**
 * @method
 * @name sliceString
 * @description slice String 처리
 * @param {String} str str
 * @param {*} start start
 * @param {*} end end
 * @returns {void}
 * @hidden N
 */
scwin.sliceString = function (str, start, end) {
    let result = '';
    const length = str.length;
    if (start < 0) {
        start = Math.max(length + start, 0);
    }
    if (end === undefined || end > length) {
        end = length;
    } else {
        if (end < 0) {
            end = length + end;
        }
    }
    for (let i = start; i < end; i++) {
        result += str[i];
    }
    return result;
};

/**
 * @method
 * @name certiManager
 * @description certi Manager 처리
 * @returns {void}
 * @hidden N
 */
scwin.certiManager = function () {
    cwInit("initCallBack");
    INIWEBEX.openCertManager({ taskNm: "", isHtml5: false });
};

/**
 * @method
 * @name goBack
 * @description go Back 처리
 * @returns {void}
 * @hidden N
 */
scwin.goBack = function () {
    moveStep = true;
    history.go(-1);
};

/**
 * @method
 * @name certification
 * @description certification 처리
 * @param {*} vidType vidType
 * @returns {void}
 * @hidden N
 */
scwin.certification = function (vidType) {
    $c.util.getComponent('dma_SignCallbackReq').set('vid', vidType);
    let DNList = "";
    if (vidType) {
        DNList = realIssuerDN;
    } else {
        DNList = testIssuerDN;
    }
    INIWEBEX.login({ loginType: "sign", data: "login", processCallback: "SignCallback", isHtml5: false, viewType: "NONE", iniCache: true, vid: vidType, langType: "KOR", filterCertByOIDAlias: { enable: false, list: "" }, filterCertByIssuer: { enable: true, list: DNList } });
};

/**
 * @method
 * @name certificationMessage
 * @description certification Message 처리
 * @param {*} meg meg
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.certificationMessage = async function (meg) {
    await $c.win.alert(meg);
    await $c.win.alert("certification");
    await scwin.submit('TEST', '', '-');
};

/**
 * @method
 * @name selectOption
 * @description select Option 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectOption = function () {
    const $selectedOptionObj = $("#slc_submitInfo option:selected");
    $c.util.getComponent('ipt_submitprnNm').setValue($selectedOptionObj.attr("submitprnNm"));
    $c.util.getComponent('ipt_telNo').setValue($selectedOptionObj.attr("telNo"));
    $c.util.getComponent('ipt_submitprnEmail').setValue($selectedOptionObj.attr("submitprnEmail"));
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} ahthSvrType ahthSvrType
 * @param {*} ahthDdtm ahthDdtm
 * @param {*} ahthKeyNo ahthKeyNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (ahthSvrType, ahthDdtm, ahthKeyNo) {
    if (($c.util.getComponent('ipt_submitprnNm').getValue() == null ? '' : String($c.util.getComponent('ipt_submitprnNm').getValue())) === '') {
        await $c.win.alert('제출인 성명을 입력하셔야 합니다.');
        $c.util.getComponent("ipt_submitprnNm").focus();
        return;
    }
    if (($c.util.getComponent('ipt_telNo').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo').getValue())) === '') {
        await $c.win.alert('전화번호를 입력하셔야 합니다.');
        $c.util.getComponent("ipt_telNo").focus();
        return;
    }
    if (($c.util.getComponent('ipt_submitprnEmail').getValue() == null ? '' : String($c.util.getComponent('ipt_submitprnEmail').getValue())) === '') {
        await $c.win.alert('이메일 정보를 입력하셔야 합니다.');
        $c.util.getComponent("ipt_submitprnEmail").focus();
        return;
    }
    $c.util.getComponent('dma_SignCallbackReq').set('ahthSvrIp', ahthSvrType);
    $c.util.getComponent('dma_SignCallbackReq').set('ahthDdtm', ahthDdtm);
    $c.util.getComponent('dma_SignCallbackReq').set('ahthKeyNo', ahthKeyNo);
    (document.submitFrm || { elements: [] }).action = '/esg/writeESGSubmitInfoForm.do?method=registerESGSubmitInformation';
    await scwin.tx_fn_submit();
};
